import { PaymentRepository } from '../repositories/payment-repository.js';
import { OrderRepository } from '../repositories/order-repository.js';
import { UserRepository } from '../repositories/user-repository.js';

const payments = new PaymentRepository();
const orders = new OrderRepository();
const users = new UserRepository();

// Payments have no deleted_at of their own: a payment is visible while its
// order is.
function onLiveOrders(rows) {
  return orders.findByIds(rows.map((p) => p.order_id)).then((live) => {
    const ids = new Set(live.map((o) => o.id));
    return rows.filter((p) => ids.has(p.order_id));
  });
}

// Keeps the callback signatures for existing callers (routes.js).
export function findPaymentsForOrder(orderId, callback) {
  payments.findByOrder(orderId)
    .then(onLiveOrders)
    .then((rows) => callback(null, rows), callback);
}

export function uncapturedTotalCents(callback) {
  payments.findUncaptured()
    .then(onLiveOrders)
    .then((rows) => callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0)), callback);
}

// Payments on the user's live orders; none for a soft-deleted user.
export function listPaymentsForUser(userId, callback) {
  users.findById(userId)
    .then((user) => (user ? orders.findByUser(userId) : []))
    .then((rows) => payments.findByOrders(rows.map((o) => o.id)))
    .then((rows) => callback(null, rows), callback);
}

