import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listActiveUsers, countActiveUsers, findUser, softDeleteUser } from '../src/services/user-service.js';
import { UserRepository } from '../src/repositories/user-repository.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('countActiveUsers counts only live users', (t, done) => {
  countActiveUsers((err, count) => {
    assert.equal(err, null);
    assert.equal(count, 2);
    done();
  });
});

test('countActiveUsers passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(UserRepository.prototype, 'findActive', () => Promise.reject(boom));
  countActiveUsers((err, count) => {
    assert.equal(err, boom);
    assert.equal(count, undefined);
    done();
  });
});

test('findUser returns a live user', (t, done) => {
  findUser(1, (err, user) => {
    assert.equal(err, null);
    assert.equal(user.email, 'ada@example.com');
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('findUser returns null for a soft-deleted user', (t, done) => {
  findUser(3, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('softDeleteUser delegates to the repository', (t, done) => {
  const softDelete = t.mock.method(UserRepository.prototype, 'softDelete',
    (id, when) => Promise.resolve({ id, deleted_at: when }));
  softDeleteUser(2, '2026-10-22', (err, row) => {
    assert.equal(err, null);
    assert.deepEqual(softDelete.mock.calls[0].arguments, [2, '2026-10-22']);
    assert.deepEqual(row, { id: 2, deleted_at: '2026-10-22' });
    done();
  });
});

test('softDeleteUser passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(UserRepository.prototype, 'softDelete', () => Promise.reject(boom));
  softDeleteUser(2, '2026-10-22', (err, row) => {
    assert.equal(err, boom);
    assert.equal(row, undefined);
    done();
  });
});
